def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in)-1)
        elif len(s_in) > len(s_out):
            return (s_in[len(s_out):], "", len(s_out))
        else:
            return ("", "", -1)  # No difference

    # Get substring from position onwards
    old_sub = ""
    new_sub = ""

    # Check if we're inserting or replacing
    if len(s_in) > len(s_out):
        # Deleting characters
        old_sub = s_in[pos]
        new_sub = ""
    elif len(s_in) < len(s_out):
        # Inserting characters  
        old_sub = ""
        new_sub = s_out[pos]
    else:
        # Replacing characters
        old_sub = s_in[pos]
        new_sub = s_out[pos]

    return (old_sub, new_sub, pos)

# Analyze the changes
changed = [(0, 'cu', 'cz'), (1, 'akwyye', 'xdkwyye')]

for idx, inp, outp in changed:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"  Minimal edit: replace '{old_sub}' with '{new_sub}' at position {pos}")

