def propose_rule_candidates(s_in, s_out):
    """Propose possible rule candidates based on the change"""
    candidates = []

    # Try simple character replacements
    if len(s_in) == len(s_out):
        # Same length - look for character substitutions
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                candidates.append((s_in[i], s_out[i]))

    # Try insertion/deletion patterns
    if len(s_out) > len(s_in):
        # Insertion - look for what's added
        added_chars = s_out[len(s_in):]
        if len(added_chars) == 1:
            candidates.append(("", added_chars))
        elif len(added_chars) > 1:
            candidates.append((s_in[:len(s_out)-len(s_in)], added_chars))

    # Try general patterns
    # Look for common substrings that might be replaced
    for length in range(1, min(len(s_in), len(s_out)) + 1):
        for i in range(len(s_in) - length + 1):
            pattern = s_in[i:i+length]
            if pattern in s_out:
                # Find replacement
                replacement = s_out[s_out.find(pattern):s_out.find(pattern)+length]
                if replacement != pattern:
                    candidates.append((pattern, replacement))

    # Add more general candidates
    if len(s_in) >= 1:
        candidates.append((s_in[0], s_out[0]))

    return candidates

# Analyze both changed pairs
changed = [(0, 'cu', 'cz'), (1, 'akwyye', 'xdkwyye')]

for idx, inp, outp in changed:
    candidates = propose_rule_candidates(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"Candidates: {candidates}")

